    \bm{m}_{t\mid t-1}&=\bm{A}\bm{m}_{t-1\mid t-1},\\
    \bm{P}_{t\mid t-1}
      &=\bm{A}\bm{P}_{t-1\mid t-1}\bm{A}^{\top}
